package com.smartinternship.model; import jakarta.persistence.*; import jakarta.validation.constraints.*; @Entity @Table(name="students") public class Student { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank private String fullName; @Email @NotBlank @Column(unique=true) private String email; @Column(length=1000) private String skills; private String preferredDomain; private Integer experienceMonths; public Student(){} public Student(String n,String e,String s,String d,Integer x){fullName=n;email=e;skills=s;preferredDomain=d;experienceMonths=x;} public Long getId(){return id;} public String getFullName(){return fullName;} public String getEmail(){return email;} public String getSkills(){return skills;} public String getPreferredDomain(){return preferredDomain;} public Integer getExperienceMonths(){return experienceMonths;} public void setId(Long x){id=x;} public void setFullName(String x){fullName=x;} public void setEmail(String x){email=x;} public void setSkills(String x){skills=x;} public void setPreferredDomain(String x){preferredDomain=x;} public void setExperienceMonths(Integer x){experienceMonths=x;} }